// Check Baileys runtime health
// Uses BAILEYS_RUNTIME_URL from env

const https = require('https');
const bailerysUrl = process.env.BAILEYS_RUNTIME_URL || 'http://localhost:3001';

const url = new URL(bailerysUrl + '/health');

const options = {
  hostname: url.hostname,
  port: url.port || 80,
  path: url.pathname,
  method: 'GET',
  timeout: 5000
};

return new Promise((resolve) => {
  const req = https.request(options, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      try {
        const json = JSON.parse(data);
        resolve({ 
          status: res.statusCode, 
          channel: 'baileys', 
          available: res.statusCode === 200,
          response: json
        });
      } catch {
        resolve({ status: res.statusCode, channel: 'baileys', available: res.statusCode === 200 });
      }
    });
  });
  req.on('error', () => resolve({ status: 0, channel: 'baileys', available: false, error: 'connection failed' }));
  req.on('timeout', () => { req.destroy(); resolve({ status: 0, channel: 'baileys', available: false, error: 'timeout' }); });
  req.end();
});

// Check Telegram Bot API status
// Uses TELEGRAM_BOT_TOKEN_STAGING env var

const https = require('https');
const token = process.env.TELEGRAM_BOT_TOKEN_STAGING;

if (!token) {
  return { channel: 'telegram', available: false, error: 'no token configured' };
}

const options = {
  hostname: 'api.telegram.org',
  port: 443,
  path: '/bot' + token + '/getMe',
  method: 'GET',
  timeout: 5000
};

return new Promise((resolve) => {
  const req = https.request(options, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      try {
        const json = JSON.parse(data);
        resolve({ 
          status: res.statusCode, 
          channel: 'telegram', 
          available: json.ok === true,
          bot_info: json.result
        });
      } catch {
        resolve({ status: res.statusCode, channel: 'telegram', available: false });
      }
    });
  });
  req.on('error', () => resolve({ status: 0, channel: 'telegram', available: false, error: 'connection failed' }));
  req.on('timeout', () => { req.destroy(); resolve({ status: 0, channel: 'telegram', available: false, error: 'timeout' }); });
  req.end();
});

// Store health status in Redis with staging: prefix
// Key format: staging:channel:health:{channel}

const bailerys = $input.all()[0].json;
const telegram = $input.all()[1].json;

const timestamp = new Date().toISOString();

// Prepare Redis keys for both channels
return [
  {
    json: {
      channel: 'baileys',
      health_key: 'staging:channel:health:baileys',
      status: bailerys.available,
      status_code: bailerys.status,
      timestamp,
      error: bailerys.error || null
    }
  },
  {
    json: {
      channel: 'telegram',
      health_key: 'staging:channel:health:telegram',
      status: telegram.available,
      status_code: telegram.status,
      timestamp,
      error: telegram.error || null
    }
  }
];

// Determine if channel is down > 5 minutes
// If current check fails AND previous check was also failure, trigger alert

const currentBaileys = $input.all()[0].json;
const currentTelegram = $input.all()[1].json;
const histBaileys = $input.all()[2].json.value === 'false';
const histTelegram = $input.all()[3].json.value === 'false';

const now = Date.now();
const FIVE_MINUTES = 5 * 60 * 1000;

const shouldAlertBaileys = !currentBaileys.available && histBaileys;
const shouldAlertTelegram = !currentTelegram.available && histTelegram;

// Calculate downtime duration (approximate - depends on poll frequency)
const baileysDown = !currentBaileys.available;
const telegramDown = !currentTelegram.available;

return [
  {
    json: {
      channel: 'baileys',
      current_status: currentBaileys.available,
      previous_status: histBaileys,
      is_down: baileysDown,
      alert_triggered: shouldAlertBaileys,
      timestamp: new Date().toISOString()
    }
  },
  {
    json: {
      channel: 'telegram',
      current_status: currentTelegram.available,
      previous_status: histTelegram,
      is_down: telegramDown,
      alert_triggered: shouldAlertTelegram,
      timestamp: new Date().toISOString()
    }
  }
];

// Build alert payload for channel failure
const channel = $input.item.json.channel;

const alertMessage = {
  alert_type: 'channel_failure',
  channel: channel,
  environment: 'staging',
  message: `⚠️ ALERT: ${channel.toUpperCase()} channel is DOWN in STAGING!`,
  timestamp: new Date().toISOString(),
  action_required: `Check ${channel} integration and restart if needed`
};

return { json: alertMessage };

// Log health check result
console.log('Staging health check completed:', {
  baileys: $input.all()[0].json,
  telegram: $input.all()[1].json
});

return { json: { logged: true } };
